head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.gViewerStat = "R"; // 처리시 뷰=P,  조회시 뷰=R
scwin.search_yn = false;
// 화면 리사이징

scwin.gAcptNo;
scwin.gIsurCd;

/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {void}
 * @hidden N
 */
scwin.onpageload = function() {
    scwin.gform_onload();
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

/**
 * @method
 * @name setCode
 * @description 현재날짜 셋팅
 * @returns {void}
 * @hidden N
 */
scwin.setCode = function() {
    // 현재날짜 셋팅
    edt_SrchDay.setValue($c.ut.cGetToday("yyyymmdd"));

    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    //
    // ********************************************************************

};X < !담당자--;
검토대상;
클릭-- > async function() {
    /*
    alert("js_bond_yn-->"+js_bond_yn);
    alert("gLdMktTp-->"+gLdMktTp);
     */
    if (edt_SrchDay.getValue().length < 8) {
        await $c.win.alert("일자 올바르게 입력하십시오.");
        edt_SrchDay.focus();
        return;
    }
    $c.cm.ShowWin_yn(grd_Grid, scwin.search_yn);
    const sbmOptions = {
        id : "sbm_dts_List",
        action : "/DisclosureSearch.do",
        ref : "",
        target : "dts_List=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    // ShowWin(grd_Grid);

};

/**
 * @method
 * @name setContnId
 * @description 그리드에서 클릭 row의 변수셋팅
 * @param {Object} obj 컴포넌트
 * @returns {void}
 * @hidden N
 */
scwin.setContnId = function(obj) {
    scwin.gAcptNo = dts_List.getCellData(Number(obj), "ACPT_NO");
    scwin.gIsurCd = dts_List.getCellData(Number(obj), "ISUR_CD");
};

/**
 * @method
 * @name grd_Grid_OnDblClick
 * @description 클릭된 값 변수에 셋팅
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_Grid_OnDblClick = async function(row, colid) {
    // 클릭된 값 변수에 셋팅
    scwin.setContnId(row);
    if (colid === "DOC_TITLE") {
        // 2017-11-29 KBoY 비공개 첨부서류 볼 수 없음.
        await $c.stf.openDisclViewer(scwin.gAcptNo, scwin.gViewerStat, 'ULDSTF15800.xml');
    } else if (colid === "ACPT_DDTM") {
        $c.stf.openDisclAllList();
    } else if (colid === "COM_ABBRV") {
        $c.stf.fn_PopupCorpInfo();
    }
};

/**
 * @method
 * @name btn_Search_onclick
 * @description 「조회」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_Search_onclick = function() {
    scwin.search_yn = true;
    fn_Search();
};

/**
 * @method
 * @name dts_List_OnLoadError
 * @description dts_List 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_List_OnLoadError = async function() {
    await $c.win.alert(dts_List);
    // CloseWin('', grd_Grid);

    scwin.search_yn = false;
};

/**
 * @method
 * @name dts_List_OnLoadCompleted
 * @description dts_List 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_List_OnLoadCompleted = async function(rowcount) {
    if (dts_List.errorMsg) {
        await $c.win.alert(dts_List.errorMsg);
    } else {
        $c.stf.fillGridHeaderTotalCnt(rowcount, panel_page);
    }

    // CloseWin(rowcount, grd_Grid);    //조회완료시 LOADING 이미지 종료

    scwin.search_yn = false;
};

/**
 * @method
 * @name btn_Excel_onclick
 * @description 「엑셀다운로드」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_Excel_onclick = function() {
    $c.stf.doLogSave('ULDSTF15800.xml', SCREN_PROCS_TP_CD_07);
    $c.data.downloadGridViewExcel(grd_Grid, {fileName: "채권시장조치알람 목록", type: "2"});
};

/**
 * @method
 * @name img_Cal_onclick
 * @description img_Cal 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.img_Cal_onclick = function() {
    popUpCalendar2(edt_SrchDay);
};

/**
 * @method
 * @name gform_onload
 * @description 리로드 시 스크립트 오류로 인해 패치함
 * @returns {void}
 * @hidden N
 */
scwin.gform_onload = function() {
    // 리로드 시 스크립트 오류로 인해 패치함

    // 패널라운드 처리
    $c.cm.PanelToGroupBox(panel_1);
    scwin.setCode();
    fn_Search();
};
